3	/// `copy_pieces` and `switch_angle` (road map "creator-jobs" SW1, spec §11
4	/// SW-11…SW-15), mirroring Clip ▸ Switch Angle ▸ (`switchAngle` in
5	/// `EditorViewController+SwitchAngle.swift`): `switch_angle` runs the menu's
6	/// own planner (`SwitchAngle.plan`) and commits it as one undo step;
7	/// `copy_pieces` is the op it writes with, one op, one undo step "Copy
8	/// Pieces". And `switch_by_speaker` (SW2b, spec §11 SW-23, SW-26), mirroring
9	/// Clip ▸ Switch by Speaker… (`SwitchSpeakerSheetController`) through the same
10	/// `SpeakerSwitch.read`, `plan` and `edit`, one undo step "Switch by Speaker";
11	/// since SW8 (spec §11 SW-86) off main, waiting for a faces mode's missing faces
12	/// where the menu shows the Analyzing sheet.
13	extension AgentServer {
14	
15	    func copyPieces(_ a: [String: Any]) throws -> String {
16	        let document = try target(a)
17	        _ = try idArg(a, "clip")
18	        _ = try idArg(a, "track")
19	        guard let ranges = try rangesArg(a, "ranges", document) else {
20	            throw ToolError(
21	                message: "Missing required argument: ranges (an array of [from, to] pairs, "
22	                    + "each a time in ticks).")
23	        }
24	        guard !ranges.isEmpty else {
25	            throw ToolError(message: "ranges is empty — name at least one [from, to] pair.")
26	        }
27	        let clip = try clipArg(a, "clip", document)
28	        let track = try trackArg(a, "track", document)
29	        let op = ReelOp.copyPieces(
30	            clip: clip.id, track: track.id, ranges: ranges,
31	            video: try boolArg(a, "video"), audio: try boolArg(a, "audio"))
32	        return try editResult(document, "Copy Pieces", [op])
33	    }
34	
35	    /// The container `set_scope` has open, as `text_behind_subject` reads it:
36	    /// no `scope` key, on the main thread, committed through
37	    /// `performGroupedEdit` (which stamps that scope on the ops).
38	    func switchAngle(_ a: [String: Any]) throws -> String {
39	        let document = try target(a)
40	        let clip = try idArg(a, "clip")
41	        let angle = try idArg(a, "angle")
42	        let container =
43	            effectiveScope(document).flatMap { document.project.scoped($0) } ?? document.project
44	        let answer: SwitchAngle.Answer
45	        do {
46	            answer = try SwitchAngle.plan(clip: clip, angle: angle, in: container)
47	        } catch let error as ToolError {
48	            throw error
49	        } catch {
50	            throw ToolError(message: error.localizedDescription)
51	        }
52	        switch answer {
53	        case .refused(let reason):
54	            throw ToolError(message: reason)
55	        case .plan(let plan):
56	            _ = try performGroupedEdit(document, plan.actionName, plan.ops)
57	            // Written by hand so the keys keep SW-15's order.
58	            let step = try JSONSerialization.data(
59	                withJSONObject: plan.actionName, options: .fragmentsAllowed)
60	            let project = try JSONSerialization.data(withJSONObject: summary(document))
61	            let pieces = plan.pieces.map(String.init).joined(separator: ",")
62	            let text = "{\"ok\":true,\"step\":\(String(decoding: step, as: UTF8.self)),"
63	                + "\"pieces\":[\(pieces)],\"transitions_removed\":\(plan.transitionsRemoved),"
64	                + "\"project\":\(String(decoding: project, as: UTF8.self))}"
65	            return try callResult(content: [["type": "text", "text": text]], isError: false)
66	        }
67	    }
