69	    // MARK: - switch_by_speaker (SW2b, SW8)
70	
71	    /// What the first hop resolved: the document, the values, and the project and scope the
72	    /// call read, which the last hop requires unchanged (SW-86).
73	    private struct SpeakerCall {
74	        let document: ProjectDocument
75	        let settings: SpeakerSwitch.Settings
76	        let pairing: SpeakerSwitch.Pairing?
77	        let range: (from: Ticks, to: Ticks)?
78	        let track: UInt32?
79	        let asked: ReelProject
80	        let scope: UInt32?
81	    }
82	
83	    /// SW-26 (c) as SW-86 amends it: on the server thread (`creatorOffMainTools`), the container
84	    /// `set_scope` has open, no `scope` key. One main hop reads the arguments, `read` and the faces
85	    /// the store still misses; with none it plans and edits in that hop. Otherwise the call wants
86	    /// them under an owner of its own and waits at most `AnalysisLane.callWaitLimit`, then a last
87	    /// hop refuses a changed project or scope, reads again and runs SW2b's sequence: Replace's
88	    /// track, `plan` and `edit`, `apply: false` answering without editing, one
89	    /// `performGroupedEdit`.
90	    func switchBySpeaker(_ a: [String: Any]) throws -> String {
91	        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
92	        guard !Thread.isMainThread else {
93	            throw ToolError(
94	                message: "switch_by_speaker must run on the server thread — its name is missing "
95	                    + "from AgentServer.creatorOffMainTools.")
96	        }
97	        let (call, wants, answer): (SpeakerCall, [SpeakerSwitch.FacesWant], String?) = try onMain {
98	            let call = try speakerCall(a)
99	            let input = try speakerInput(call)
100	            let wants: [SpeakerSwitch.FacesWant]
101	            do {
102	                wants = try SpeakerSwitch.facesWanted(input, in: call.document)
103	            } catch {
104	                throw ToolError(message: error.localizedDescription)
105	            }
106	            guard wants.isEmpty else { return (call, wants, nil) }
107	            return (call, wants, try finishSpeakerSwitch(a, call, input))
108	        }
109	        if let answer { return answer }
110	        try waitForFaces(wants, document: call.document, stop: stop)
111	        return try onMain {
112	            guard call.document.project === call.asked, call.document.scope == call.scope else {
113	                throw ToolError(
114	                    message: "the project changed while \(SpeakerSwitch.actionName) was "
115	                        + "analyzing, so nothing was switched. Call switch_by_speaker again.")
116	            }
117	            return try finishSpeakerSwitch(a, call, try speakerInput(call))
118	        }
119	    }
120	
121	    /// SW-26 (c)'s arguments and errors, and the pairing: a named `wide` without `speakers` drops
122	    /// a shared-microphone speaker on it (SW-83); `min_shot` absent is 3 s in the faces mode.
123	    private func speakerCall(_ a: [String: Any]) throws -> SpeakerCall {
124	        let document = try target(a)
125	        var settings = try speakerSettings(a)
126	        let fps = document.editedProject.snapshot.canvas.fps
127	        let from = try intArg(a, "from").map { ReelTime.snapToFrame(Ticks($0), fps: fps) }
128	        let to = try intArg(a, "to").map { ReelTime.snapToFrame(Ticks($0), fps: fps) }
129	        if (from == nil) != (to == nil) {
130	            throw ToolError(message: "Name both from and to, or neither.")
131	        }
132	        if let from, let to, to <= from {
133	            throw ToolError(message: "to (\(to)) must be after from (\(from)) on the frame grid.")
134	        }
135	        let scope = try idScope(document)
136	        func trackID(_ raw: Any?, _ key: String) throws -> UInt32 {
137	            guard let number = raw as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID(),
138	                let value = Self.whole(number), value >= 0, value <= Int(UInt32.max)
139	            else { throw ToolError(message: "\(key) must be a track id (an integer).") }
140	            guard scope.track(UInt32(value)) != nil else {
141	                throw ToolError(message: "no track with id \(value)")
142	            }
143	            return UInt32(value)
144	        }
145	        var speakers: [SpeakerSwitch.Speaker]?
146	        if let raw = a["speakers"], !(raw is NSNull) {
147	            guard let rows = raw as? [Any], !rows.isEmpty else {
148	                throw ToolError(
149	                    message: "speakers must be an array of {mic, angle} objects, at least one.")
150	            }
151	            speakers = try rows.map { row in
152	                guard let item = row as? [String: Any] else {
153	                    throw ToolError(message: "each of speakers must be an object {mic, angle}.")
154	                }
155	                if let stranger = item.keys.sorted().first(where: { $0 != "mic" && $0 != "angle" })
156	                {
157	                    throw ToolError(
158	                        message: "speakers: unknown key \(stranger); each speaker is {mic, angle}.")
159	                }
160	                return SpeakerSwitch.Speaker(
161	                    mic: try trackID(item["mic"], "a speaker's mic"),
162	                    angle: try trackID(item["angle"], "a speaker's angle"))
163	            }
164	        }
165	        let snapshot = document.editedProject.snapshot
166	        let selected = document.selection.sorted().compactMap { snapshot.clip($0) }
167	        let implied = SpeakerSwitch.defaults(selection: selected, in: snapshot)
168	        var wide: UInt32?
169	        let wideNamed = a.keys.contains("wide")
170	        if let raw = a["wide"], !(raw is NSNull) {
171	            let id = try trackID(raw, "wide")
172	            guard implied.angles.contains(id) else {
173	                throw ToolError(message: "wide: track \(id) is not an angle")
174	            }
175	            wide = id
176	        }
177	        let track = try a["track"].flatMap { $0 is NSNull ? nil : $0 }.map {
178	            try trackID($0, "track")
179	        }
180	
181	        // `wide` absent: SW-20's leftover rule over the speakers used.
182	        let pairing: SpeakerSwitch.Pairing?
183	        if let speakers {
184	            if !wideNamed {
185	                let used = Set(speakers.compactMap(\.angle))
186	                let left = implied.angles.filter { !used.contains($0) }
187	                wide = left.count == 1 ? left.first : nil
188	            }
189	            pairing = SpeakerSwitch.Pairing(speakers: speakers, wide: wide)
190	        } else {
191	            pairing = wideNamed
192	                ? SpeakerSwitch.withoutWide(
193	                    SpeakerSwitch.Pairing(speakers: implied.pairing.speakers, wide: wide)) : nil
194	        }
195	        if a["min_shot"] == nil || a["min_shot"] is NSNull,
196	            SpeakerSwitch.mode(pairing ?? implied.pairing) == .faces
197	        {
198	            settings.minShot = FaceActivity.minShot  // SW-82
199	        }
200	        let range = from.flatMap { f in to.map { (from: f, to: $0) } }
201	        return SpeakerCall(
202	            document: document, settings: settings, pairing: pairing, range: range, track: track,
203	            asked: document.project, scope: document.scope)
204	    }
205	
206	    private func speakerInput(_ call: SpeakerCall) throws -> SpeakerSwitch.Input {
207	        guard
208	            let input = SpeakerSwitch.read(
209	                from: call.document, clips: nil, pairing: call.pairing, range: call.range,
210	                settings: call.settings)
211	        else {
212	            throw ToolError(
213	                message: "The project's audio plan could not be read, so Switch by Speaker "
214	                    + "cannot run. Try again in a moment.")
215	        }
216	        return input
217	    }
218	
219	    /// SW2b's sequence over `input`, main thread: Replace's track, `plan`, `edit`, then the edit
220	    /// unless `apply` is false, and the answer with SW-86's `mode` and, in the faces mode, `note`.
221	    private func finishSpeakerSwitch(
222	        _ a: [String: Any], _ call: SpeakerCall, _ input: SpeakerSwitch.Input
223	    ) throws -> String {
224	        let document = call.document
225	        let track = call.track
226	        let snapshot = document.editedProject.snapshot
227	        let refused = "Switch by Speaker was refused: "
228	        if let track,
229	            let why = SpeakerSwitch.replaceRefusal(
230	                track, input: input, selection: document.selection, in: snapshot)
231	        {
232	            throw ToolError(message: refused + why)
233	        }
234	        guard case .planned(let shots, let added) = SpeakerSwitch.plan(input) else {
235	            if case .refused(let reasons) = SpeakerSwitch.plan(input) {
236	                throw ToolError(message: refused + reasons.joined(separator: " "))
237	            }
238	            throw ToolError(message: refused + "nothing was planned.")
239	        }
240	        let mute = try boolArg(a, "mute_cameras") ?? SpeakerSwitch.muteDefault(input)
241	        let answer: SpeakerSwitch.EditAnswer
242	        do {
243	            answer = try SpeakerSwitch.edit(
244	                shots, input: input, muteCameras: mute, replacing: track,
245	                selection: document.selection, in: document.editedProject)
246	        } catch {
247	            throw ToolError(message: error.localizedDescription)
248	        }
249	        let edit: SpeakerSwitch.Edit
250	        switch answer {
251	        case .refused(let why):
252	            // (a)'s refusal already says where; (h)'s is the bare sentence.
253	            throw ToolError(
254	                message: why.hasPrefix("Switch by Speaker was refused") ? why : refused + why)
255	        case .edit(let made):
256	            edit = made
257	        }
258	
259	        let apply = try boolArg(a, "apply") ?? true
260	        if apply {
261	            try performGroupedEdit(document, SpeakerSwitch.actionName, edit.ops)
262	            document.selection = edit.selection
263	        }
264	        func id(_ value: UInt32?) -> Any { value.map { NSNumber(value: $0) } ?? NSNull() }
265	        var fields: [String: Any] = [
266	            "ok": true,
267	            "applied": apply,
268	            "track": apply || track != nil ? id(edit.track) : NSNull(),
269	            "shots": shots.map { ["angle": $0.angle, "start": $0.start, "end": $0.end] },
270	            "ops": edit.ops.count,
271	            "added": added,
272	            "speakers": input.pairing.speakers.map { ["mic": id($0.mic), "angle": id($0.angle)] },
273	            "wide": id(input.pairing.wide),
274	            "mute_cameras": mute,
275	            "project": summary(document),
276	        ]
277	        if apply { fields["step"] = SpeakerSwitch.actionName }
278	        let mode = SpeakerSwitch.mode(input.pairing)
279	        fields["mode"] = mode.rawValue
280	        if mode == .faces { fields["note"] = FaceActivity.hedge }
281	        return try jsonResult(fields)
282	    }
283	
284	    /// Wants every request under an owner of the call's own and waits (`waitForShots`' shape);
285	    /// throws naming the first media not landed when one failed, the call was stopped, or the
286	    /// bound passed (SW-86).
287	    private func waitForFaces(
288	        _ wants: [SpeakerSwitch.FacesWant], document: ProjectDocument, stop: AgentCallCancel?
289	    ) throws {
290	        let lane = AnalysisLane.shared
291	        let requests = wants.map(\.request)
292	        let owner = lane.newOwner()
293	        defer { lane.release(owner: owner) }
294	        lane.want(
295	            requests, owner: owner,
296	            alive: { document.isOpenForAnalysis && !(stop?.isCancelled ?? false) },
297	            settled: { document.packageContentsDidChangeOnDisk() })
298	        let outcome = lane.wait(
299	            for: requests, owner: owner,
300	            deadline: Date().addingTimeInterval(AnalysisLane.callWaitLimit),
301	            cancelled: { stop?.isCancelled ?? false })
302	        let open = wants.first { lane.run(of: $0.request)?.outcome != .landed } ?? wants[0]
303	        let media = open.media.id
304	        switch outcome {
305	        case .landed: return
306	        case .failed(let why):
307	            throw ToolError(message: "The faces analysis of media \(media) failed: \(why).")
308	        case .cancelled:
309	            throw ToolError(
310	                message: "The faces analysis of media \(media) was stopped before it finished, "
311	                    + "so nothing was switched.")
312	        case .timedOut:
313	            throw ToolError(
314	                message: "The faces analysis of media \(media) did not finish in the "
315	                    + "\(Int(AnalysisLane.callWaitLimit)) s a call waits; what it covered is "
316	                    + "kept — call switch_by_speaker again to continue.")
317	        }
318	    }
319	
320	    /// SW-26's numbers and `crosstalk`, each refused outside its range in auto_zoom's form.
321	    private func speakerSettings(_ a: [String: Any]) throws -> SpeakerSwitch.Settings {
322	        typealias S = SpeakerSwitch.Settings
323	        func plain(_ v: Double) -> String {
324	            v.rounded() == v && abs(v) < 1e15 ? String(Int64(v)) : String(v)
325	        }
326	        func number(_ key: String, _ unit: String, _ range: ClosedRange<Double>) throws
327	            -> Double?
328	        {
329	            guard let v = try doubleArg(a, key) else { return nil }
330	            guard v.isFinite, range.contains(v) else {
331	                throw ToolError(
332	                    message: "\(key) is \(plain(v))\(unit); it runs "
333	                        + "\(plain(range.lowerBound))–\(plain(range.upperBound))\(unit).")
334	            }
335	            return v
336	        }
337	        var s = S()
338	        s.minShot = try number("min_shot", " s", S.minShotRange) ?? s.minShot
339	        s.minTurn = try number("min_turn", " s", S.minTurnRange) ?? s.minTurn
340	        s.lead = try number("lead", " s", S.leadRange) ?? s.lead
341	        s.bleedDB = try number("bleed_db", " dB", S.bleedRange) ?? s.bleedDB
342	        s.dominanceDB = try number("dominance_db", " dB", S.dominanceRange) ?? s.dominanceDB
343	        s.wideAfter = try number("wide_after", " s", S.wideAfterRange)
344	        if let crosstalk = try stringArg(a, "crosstalk") {
345	            guard let value = SpeakerSwitch.Crosstalk(rawValue: crosstalk) else {
346	                throw ToolError(
347	                    message: "crosstalk is \"\(crosstalk)\"; it is \"wide\" or \"hold\".")
348	            }
349	            s.crosstalk = value
350	        }
351	        return s
352	    }
353	}
