173	    /// VR-36's first hop, its refusals in order.
174	    private func resolveVertical(_ a: [String: Any]) throws -> VerticalCall {
175	        let document = try target(a)
176	        let shape = try requiredEnumArg(a, "shape", VerticalShape.self)
177	        var follow = FramingFollow.subject
178	        if let raw = try stringArg(a, "follow") {
179	            guard let kind = FramingFollow(rawValue: raw), VerticalVersion.follows.contains(kind)
180	            else {
181	                throw ToolError(
182	                    message: "follow must be subject, face, person, salient, speaker or center, "
183	                        + "not \(raw).")
184	            }
185	            follow = kind
186	        }
187	        let zoom = try doubleArg(a, "zoom") ?? 1
188	        let whereEmpty = try enumArg(a, "where_empty", FramingWhereEmpty.self) ?? .fit
189	        let copy = try boolArg(a, "copy") ?? true
190	        let captions = try boolArg(a, "captions") ?? true
191	        let path = try stringArg(a, "path")
192	        guard document.scope == nil else {
193	            throw ToolError(
194	                message: "make_vertical_version works on the top-level timeline: set_scope with "
195	                    + "no nest first.")
196	        }
197	        if path != nil, !copy {
198	            throw ToolError(
199	                message: "make_vertical_version writes path only for a copy: drop path, or copy.")
200	        }
201	        let url = path.map {
202	            Self.destinationURL($0, extension: ProjectDocument.projectFileExtension)
203	        }
204	        if let url {
205	            try refuseHeldPath(url, except: nil, tool: "make_vertical_version")
206	            guard !FileManager.default.fileExists(atPath: url.path) else {
207	                throw ToolError(
208	                    message: "\(url.path) already exists, so make_vertical_version did not "
209	                        + "write there: pass a new path.")
210	            }
211	        }
212	        let project = document.project
213	        let canvas = project.snapshot.canvas
214	        let size = shape.size(from: canvas)
215	        guard size.width != canvas.width || size.height != canvas.height else {
216	            throw ToolError(
217	                message: "the canvas is already \(canvas.width) × \(canvas.height), so there is "
218	                    + "no \(shape.rawValue) version to make.")
219	        }
220	        do {
221	            if case .refused(let why) = try VerticalVersion.opening(
222	                project, width: size.width, height: size.height)
223	            {
224	                throw ToolError(message: why)
225	            }
226	        } catch let error as ToolError {
227	            throw error
228	        } catch {
229	            throw ToolError(message: error.localizedDescription)
230	        }
231	        // VR-64 (a), (e): the microphones, read only with speaker.
232	        var mics: [UInt32] = []
233	        var micFaces: [UInt32]?
234	        if follow == .speaker {
235	            guard let given = try numbersArg(a, "mics"), !given.isEmpty else {
236	                throw ToolError(
237	                    message: "make_vertical_version's follow speaker needs mics: two to four "
238	                        + "clips, one on each microphone's track.")
239	            }
240	            for id in given { _ = try clipArg(["clip": Int(id)], "clip", document) }
241	            mics = given
242	            micFaces = try numbersArg(a, "mic_faces")
243	        }
244	        let settings = VerticalSettings(
245	            shape: shape, follow: follow, zoom: zoom, whereEmpty: whereEmpty, captions: captions,
246	            mics: mics, micFaces: micFaces)
247	        let (present, missing, cursor) = VerticalVersion.analysisTargets(
248	            project, urls: document.mediaURLs())
249	        if follow == .speaker,
250	            VerticalVersion.speakerClips(project, settings: settings, missing: missing).isEmpty
251	        {
252	            throw ToolError(message: VerticalVersion.noSpeakerClip)
253	        }
254	        // The dry plan: the core's error for a bad argument, before any analysis. Its
255	        // refusal and its plan are discarded.
256	        do {
257	            _ = try VerticalVersion.plan(
258	                project, settings: settings, subjects: [:], missing: missing)
259	        } catch {
260	            throw ToolError(message: error.localizedDescription)
261	        }
262	        let analysed = VerticalVersion.analyses(follow)
263	        let targets = analysed ? present : []
264	        var requests: [AnalysisRequest] = []
265	        var cacheDir: URL?
266	        if !targets.isEmpty {
267	            guard let folder = document.cacheDirectory else {
268	                throw ToolError(
269	                    message: ProjectDocument.AnalysisRequestError.noCache.localizedDescription)
270	            }
271	            cacheDir = folder
272	            do {
273	                requests = try FramingAnalysis.requests(
274	                    clips: targets, in: document, project: project)
275	            } catch {
276	                throw ToolError(message: error.localizedDescription)
277	            }
278	        }
279	        return VerticalCall(
280	            document: document, settings: settings, copy: copy, url: url, missing: missing,
281	            targets: targets, cursor: analysed ? cursor : [],
282	            requests: requests, cacheDir: cacheDir, asked: project, scope: document.scope)
283	    }
