121	    /// SW-26 (c)'s arguments and errors, and the pairing: a named `wide` without `speakers` drops
122	    /// a shared-microphone speaker on it (SW-83); `min_shot` absent is 3 s in the faces mode.
123	    private func speakerCall(_ a: [String: Any]) throws -> SpeakerCall {
124	        let document = try target(a)
125	        var settings = try speakerSettings(a)
126	        let fps = document.editedProject.snapshot.canvas.fps
127	        let from = try intArg(a, "from").map { ReelTime.snapToFrame(Ticks($0), fps: fps) }
128	        let to = try intArg(a, "to").map { ReelTime.snapToFrame(Ticks($0), fps: fps) }
129	        if (from == nil) != (to == nil) {
130	            throw ToolError(message: "Name both from and to, or neither.")
131	        }
132	        if let from, let to, to <= from {
133	            throw ToolError(message: "to (\(to)) must be after from (\(from)) on the frame grid.")
134	        }
135	        let scope = try idScope(document)
136	        func trackID(_ raw: Any?, _ key: String) throws -> UInt32 {
137	            guard let number = raw as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID(),
138	                let value = Self.whole(number), value >= 0, value <= Int(UInt32.max)
139	            else { throw ToolError(message: "\(key) must be a track id (an integer).") }
140	            guard scope.track(UInt32(value)) != nil else {
141	                throw ToolError(message: "no track with id \(value)")
142	            }
143	            return UInt32(value)
144	        }
145	        var speakers: [SpeakerSwitch.Speaker]?
146	        if let raw = a["speakers"], !(raw is NSNull) {
147	            guard let rows = raw as? [Any], !rows.isEmpty else {
148	                throw ToolError(
149	                    message: "speakers must be an array of {mic, angle} objects, at least one.")
150	            }
151	            speakers = try rows.map { row in
152	                guard let item = row as? [String: Any] else {
153	                    throw ToolError(message: "each of speakers must be an object {mic, angle}.")
154	                }
155	                if let stranger = item.keys.sorted().first(where: { $0 != "mic" && $0 != "angle" })
156	                {
157	                    throw ToolError(
158	                        message: "speakers: unknown key \(stranger); each speaker is {mic, angle}.")
159	                }
160	                return SpeakerSwitch.Speaker(
161	                    mic: try trackID(item["mic"], "a speaker's mic"),
162	                    angle: try trackID(item["angle"], "a speaker's angle"))
163	            }
164	        }
165	        let snapshot = document.editedProject.snapshot
166	        let selected = document.selection.sorted().compactMap { snapshot.clip($0) }
167	        let implied = SpeakerSwitch.defaults(selection: selected, in: snapshot)
168	        var wide: UInt32?
169	        let wideNamed = a.keys.contains("wide")
170	        if let raw = a["wide"], !(raw is NSNull) {
171	            let id = try trackID(raw, "wide")
172	            guard implied.angles.contains(id) else {
173	                throw ToolError(message: "wide: track \(id) is not an angle")
174	            }
175	            wide = id
176	        }
177	        let track = try a["track"].flatMap { $0 is NSNull ? nil : $0 }.map {
178	            try trackID($0, "track")
179	        }
180	
181	        // `wide` absent: SW-20's leftover rule over the speakers used.
182	        let pairing: SpeakerSwitch.Pairing?
183	        if let speakers {
184	            if !wideNamed {
185	                let used = Set(speakers.compactMap(\.angle))
186	                let left = implied.angles.filter { !used.contains($0) }
187	                wide = left.count == 1 ? left.first : nil
188	            }
189	            pairing = SpeakerSwitch.Pairing(speakers: speakers, wide: wide)
190	        } else {
191	            pairing = wideNamed
192	                ? SpeakerSwitch.withoutWide(
193	                    SpeakerSwitch.Pairing(speakers: implied.pairing.speakers, wide: wide)) : nil
194	        }
195	        if a["min_shot"] == nil || a["min_shot"] is NSNull,
196	            SpeakerSwitch.mode(pairing ?? implied.pairing) == .faces
197	        {
198	            settings.minShot = FaceActivity.minShot  // SW-82
199	        }
200	        let range = from.flatMap { f in to.map { (from: f, to: $0) } }
201	        return SpeakerCall(
202	            document: document, settings: settings, pairing: pairing, range: range, track: track,
203	            asked: document.project, scope: document.scope)
204	    }
