285	    /// `relay_captions` (road map "creator-jobs" VR4a, spec §11 VR-45): the word caption
286	    /// tracks of the container `set_scope` has open re-paged on its canvas as one undo step
287	    /// "Re-lay Captions" — what File ▸ Re-lay Captions for This Canvas does
288	    /// (`EditorViewController+RelayCaptions.swift`). Main thread; no `scope` argument, since
289	    /// dispatch reads `scope` only for op names; it plans on `editedProject` and
290	    /// `performGroupedEdit` addresses the ops.
291	    func relayCaptions(_ a: [String: Any]) throws -> String {
292	        let document = try target(a)
293	        let planned: (ops: [ReelOp], outcome: CaptionRelayout.Outcome)
294	        do {
295	            planned = try CaptionRelayout.plan(document.editedProject)
296	        } catch {
297	            throw ToolError(message: error.localizedDescription)
298	        }
299	        guard !planned.ops.isEmpty else {
300	            let kept = planned.outcome.kept.map { "\"\($0.name)\": \($0.reason)" }
301	            throw ToolError(
302	                message: "relay_captions found no caption track it can re-lay: "
303	                    + (kept.isEmpty
304	                        ? "there is no track named Captions holding only text clips"
305	                        : kept.joined(separator: "; ")))
306	        }
307	        return try editResult(
308	            document, CaptionRelayout.actionName, planned.ops,
309	            CaptionRelayout.answerFields(planned.outcome))
310	    }
311	}
