224	/// The framing (spec §11 VR-60, VR-61): `mics` checked by the op before;
225	/// `Err` is the refusal's sentence, in VR-60 (d)'s order.
226	pub fn plan_speaker_framing(
227	    project: &Project,
228	    clip: u32,
229	    subjects: &Subjects,
230	    mics: &[u32],
231	    mic_faces: Option<&[u32]>,
232	    zoom: f64,
233	    where_empty: WhereEmpty,
234	) -> Result<FramingPath, String> {
235	    let picture = || format!("clip {clip}'s crop or scale leaves no picture to frame");
236	    let c = project.clip(clip).ok_or_else(picture)?;
237	    let Source::Media { media, .. } = c.source else {
238	        return Err(picture());
239	    };
240	    if !project
241	        .media(media)
242	        .is_some_and(|m| m.kind == MediaKind::Video && m.has_video)
243	    {
244	        return Err(picture());
245	    }
246	    if let Some((i, turn)) = subjects
247	        .turns
248	        .iter()
249	        .enumerate()
250	        .find(|(_, u)| !mics.contains(&u.mic))
251	    {
252	        return Err(format!(
253	            "subjects turns[{i}] names clip {}, which is not one of mics",
254	            turn.mic
255	        ));
256	    }
257	    let request = FramingRequest {
258	        follow: Follow::Face,
259	        zoom,
260	        from_width: project.canvas.width,
261	        from_height: project.canvas.height,
262	        where_empty,
263	    };
264	    let mut frame = Frame::of(project, c, &request).ok_or_else(picture)?;
265	    let (samples, shots) = in_clip_time(c, project, subjects);
266	    if let Some(&shot) = shots.first() {
267	        return Err(format!(
268	            "clip {clip} changes shot at {}; follow speaker frames one wide shot — split the \
269	             clip at its shot changes first",
270	            project.layout_timecode(c.start + shot)
271	        ));
272	    }
273	    if !c.actions.is_empty() {
274	        frame.placed = samples
275	            .iter()
276	            .map(|s| {
277	                let p = project.evaluate_clip(c, s.t).video;
278	                (s.t, p.scale, p.x, p.y)
279	            })
280	            .collect();
281	    }
282	    let turns = clip_turns(c, &subjects.turns);
283	    let faces = faces_of(&samples);
284	    let plural = |n: usize| if n == 1 { "face" } else { "faces" };
285	    let Some(found) = matched(&samples, &faces, &turns, mics) else {
286	        return Err(format!(
287	            "clip {clip} shows {} {} for {} microphones; follow speaker needs a face for each \
288	             microphone",
289	            faces.len(),
290	            plural(faces.len()),
291	            mics.len()
292	        ));
293	    };
294	    if let Some(&f) = mic_faces
295	        .into_iter()
296	        .flatten()
297	        .find(|&&f| f as usize > faces.len())
298	    {
299	        return Err(format!(
300	            "mic_faces names face {f}, but clip {clip} shows only {} {}",
301	            faces.len(),
302	            plural(faces.len())
303	        ));
304	    }
305	    let no_turn = || {
306	        format!(
307	            "clip {clip} has no turn of its microphones inside it, so there is no speaker to \
308	             follow"
309	        )
310	    };
311	    if turns.is_empty() {
312	        return Err(no_turn());
313	    }
314	    let assignment: Vec<u32> = match mic_faces {
315	        Some(given) => given.to_vec(),
316	        None if found.sure => found.assignment.clone(),
317	        None => {
318	            let least = (0..mics.len())
319	                .map(|m| found.agreement[m][found.assignment[m] as usize - 1])
320	                .fold(f64::INFINITY, f64::min);
321	            let places: Vec<String> = found
322	                .faces
323	                .iter()
324	                .enumerate()
325	                .map(|(n, f)| {
326	                    let at = format!("face {} at {} %", f.face, (f.x * 100.0).round());
327	                    if n == 0 {
328	                        format!("{at} across the picture")
329	                    } else {
330	                        at
331	                    }
332	                })
333	                .collect();
334	            return Err(format!(
335	                "clip {clip}'s faces do not show which microphone is whose: the best match \
336	                 agrees only {least:.2} (under {SPEAKER_AGREEMENT}); name each microphone's face \
337	                 with mic_faces, in mics' order — {}",
338	                places.join(", ")
339	            ));
340	        }
341	    };
342	    let index: Vec<usize> = assignment.iter().map(|&f| f as usize - 1).collect();
343	    let fits = |a: usize, b: usize, from: Ticks, to: Ticks| {
344	        let widened = |f: usize| {
345	            let m = median_box(&faces[f], &samples, from, to);
346	            let (cx, cy) = centre(&m);
347	            let (w, h) = (m.w * PAIR_WIDEN, m.h * PAIR_WIDEN);
348	            (cx - w / 2.0, cy - h / 2.0, cx + w / 2.0, cy + h / 2.0)
349	        };
350	        let (p, q) = (widened(a), widened(b));
351	        let p0 = frame.point(from, p.0.min(q.0), p.1.min(q.1));
352	        let p1 = frame.point(from, p.2.max(q.2), p.3.max(q.3));
353	        p1.0 - p0.0 <= frame.window.0 && p1.1 - p0.1 <= frame.window.1
354	    };
355	    let segments = segments(c.duration, &turns, mics, &index, fits).ok_or_else(no_turn)?;
356	    let cuts: Vec<Ticks> = segments.iter().map(|s| s.from).filter(|&t| t > 0).collect();
357	    let chosen: Vec<Chosen> = samples
358	        .iter()
359	        .enumerate()
360	        .map(|(i, s)| {
361	            let n = segments
362	                .partition_point(|g| g.to <= s.t)
363	                .min(segments.len() - 1);
364	            let (face, other) = match segments[n].label {
365	                Label::Face(f) => (f, None),
366	                Label::Both(f, o) => (f, Some(o)),
367	            };
368	            Chosen {
369	                t: s.t,
370	                kind: Some(SubjectKind::Face),
371	                track: Some(face as u32 + 1),
372	                subject: faces[face].at(i),
373	                identity: Some(face as u32 + 1),
374	                lost: false,
375	                second: other.and_then(|o| faces[o].at(i)),
376	            }
377	        })
378	        .collect();
379	    Ok(write_keys(
380	        &frame,
381	        &chosen,
382	        &cuts,
383	        c.duration,
384	        project.canvas.fps,
385	        &request,
386	        &FRAMING_TUNING,
387	    ))
388	}
