48	/// One layout action: its clip, its id and its absolute start.
49	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
50	struct Act {
51	    clip: u32,
52	    action: u32,
53	    at: Ticks,
54	}
55	
56	/// A recognised switch: the camera's action, the screen's paired one, the
57	/// layout, and each role's pieces.
58	struct Switch {
59	    camera: Act,
60	    screen: Option<Act>,
61	    choice: LayoutChoice,
62	    camera_pieces: Vec<u32>,
63	    screen_pieces: Vec<u32>,
64	}
65	
66	/// The duration and curve a switch is replayed with: those of its longest
67	/// role action that does not start at its clip's first frame (a cut there
68	/// is one frame long whatever the switch's length), else the camera
69	/// action's — `actions` holds the camera's first.
70	pub(crate) fn switch_timing(actions: &[(&Clip, &Action)]) -> (Ticks, Curve) {
71	    let mut chosen: Option<&Action> = None;
72	    for (_, action) in actions {
73	        if action.start != 0 && chosen.is_none_or(|c| action.duration > c.duration) {
74	            chosen = Some(action);
75	        }
76	    }
77	    match chosen.or(actions.first().map(|(_, a)| *a)) {
78	        Some(action) => (action.duration, action.curve),
79	        None => (DEFAULT_SWITCH, Curve::EaseInOut),
80	    }
81	}
82	
83	/// A moving end re-based from the placement `old` it was made over to
84	/// `new`: with `r = new.scale / old.scale`, each of `x`, `y` and `scale`
85	/// the end names is written `new.x + r·(x − old.x)`, `new.y + r·(y − old.y)`
86	/// and `scale·r` (clamped), so the picture point it shows at a canvas point
87	/// keeps its place relative to the layout's picture.
88	pub(crate) fn conjugate(end: &mut Map<String, Value>, old: &Placement, new: &Placement) {
89	    let r = new.scale / old.scale;
90	    if !(r.is_finite() && r > 0.0) {
91	        return;
92	    }
93	    let read = |end: &Map<String, Value>, key: &str| end.get(key).and_then(Value::as_f64);
94	    if let Some(x) = read(end, "x") {
95	        end.insert("x".into(), Value::from(new.x + r * (x - old.x)));
96	    }
97	    if let Some(y) = read(end, "y") {
98	        end.insert("y".into(), Value::from(new.y + r * (y - old.y)));
99	    }
100	    if let Some(scale) = read(end, "scale") {
101	        end.insert(
102	            "scale".into(),
103	            Value::from((scale * r).clamp(SCALE_MIN, SCALE_MAX)),
104	        );
105	    }
106	}
107	
108	/// The layout actions of `clip`, in its action order.
109	fn layout_acts(clip: &Clip) -> Vec<Act> {
110	    clip.actions
111	        .iter()
112	        .filter(|a| is_layout(a))
113	        .map(|a| Act {
114	            clip: clip.id,
115	            action: a.id,
116	            at: clip.start.saturating_add(a.start),
117	        })
118	        .collect()
119	}
120	
121	/// The placement in effect at clip time `t`: the latest layout end starting
122	/// at or before it, else the base.
123	fn in_effect(clip: &Clip, t: Ticks) -> Placement {
124	    clip.actions
125	        .iter()
126	        .filter(|a| is_layout(a) && a.start <= t)
127	        .max_by_key(|a| (a.start, a.id))
128	        .and_then(|a| Placement::from_end(&a.end))
129	        .unwrap_or_else(|| Placement::of(&clip.video.clone().unwrap_or_default()))
130	}
