124	/// The geometry one plan reads: the clip's placement on the source canvas,
125	/// the common cropped rect (VR-27 (a)), and the window.
126	pub(crate) struct Frame {
127	    pub(crate) anchor: Point,
128	    pub(crate) s: f64,
129	    pub(crate) media: Point,
130	    pub(crate) rect: (Point, Point),
131	    /// The placement in force at each in-clip sample tick, `(tick, scale, x,
132	    /// y)`, sorted; empty for a clip with no actions, whose points read the
133	    /// base (VR-27 (a)).
134	    pub(crate) placed: Vec<(Ticks, f64, f64, f64)>,
135	    pub(crate) k: f64,
136	    pub(crate) window: Point,
137	    pub(crate) half_source: Point,
138	    /// The `fit` state as a key of F: `(k, dx, dy)` (VR-24 (h)).
139	    pub(crate) fit: (f64, f64, f64),
140	}
141	
142	impl Frame {
143	    /// The geometry of `clip`, sized through [`Project::source_size`]; `None`
144	    /// for no size, a base rotation other than 0, a zoom outside 1…4, a zero
145	    /// source canvas, or a crop or scale that leaves no picture.
146	    pub(crate) fn of(project: &Project, clip: &Clip, request: &FramingRequest) -> Option<Frame> {
147	        let video = clip.video.clone().unwrap_or_default();
148	        if video.rotation != 0.0 {
149	            return None;
150	        }
151	        let (mw, mh) = project.source_size(clip)?;
152	        let zoom = request.zoom;
153	        let (ws, hs) = (
154	            f64::from(request.from_width),
155	            f64::from(request.from_height),
156	        );
157	        if mw <= 0.0 || mh <= 0.0 || !(1.0..=4.0).contains(&zoom) || ws <= 0.0 || hs <= 0.0 {
158	            return None;
159	        }
160	        let crop = video.crop;
161	        let (cw, ch) = (mw - crop.l - crop.r, mh - crop.t - crop.b);
162	        let s = video.scale;
163	        if !(cw > 0.0 && ch > 0.0 && s.is_finite() && s > 0.0) {
164	            return None;
165	        }
166	        let anchor = (ws / 2.0 + video.x, hs / 2.0 + video.y);
167	        let c = ((crop.l - crop.r) / 2.0, (crop.t - crop.b) / 2.0);
168	        let rect_of = |s: f64, anchor: Point| {
169	            (
170	                (
171	                    anchor.0 + s * (c.0 - cw / 2.0),
172	                    anchor.1 + s * (c.1 - ch / 2.0),
173	                ),
174	                (
175	                    anchor.0 + s * (c.0 + cw / 2.0),
176	                    anchor.1 + s * (c.1 + ch / 2.0),
177	                ),
178	            )
179	        };
180	        let base_rect = rect_of(s, anchor);
181	        let (w, h) = (
182	            f64::from(project.canvas.width),
183	            f64::from(project.canvas.height),
184	        );
185	        // VR-27 (a): the common rect over the base and every action's end,
186	        // and the largest scale among them.
187	        let (mut rect, mut s_max) = (base_rect, s);
188	        for a in &clip.actions {
189	            let p = project
190	                .evaluate_clip(clip, a.start.saturating_add(a.duration))
191	                .video;
192	            if !(p.scale.is_finite() && p.scale > 0.0 && p.x.is_finite() && p.y.is_finite()) {
193	                continue;
194	            }
195	            let ((x0, y0), (x1, y1)) = rect_of(p.scale, (ws / 2.0 + p.x, hs / 2.0 + p.y));
196	            rect = (
197	                (rect.0 .0.max(x0), rect.0 .1.max(y0)),
198	                (rect.1 .0.min(x1), rect.1 .1.min(y1)),
199	            );
200	            s_max = s_max.max(p.scale);
201	        }
202	        let ((x0, y0), (x1, y1)) = rect;
203	        if !(x0 < x1 && y0 < y1) {
204	            rect = base_rect;
205	        }
206	        let mut k = (zoom * project.fill_scale(cw, ch)).min(SCALE_MAX) / s;
207	        // Only a smaller rect raises `k`, so an action-free clip's `k` is
208	        // VR2a2's to the bit.
209	        let raised = rect != base_rect;
210	        if raised {
211	            let ((x0, y0), (x1, y1)) = rect;
212	            k = k.max(w / (x1 - x0)).max(h / (y1 - y0));
213	        }
214	        if raised || s_max > s {
215	            k = k.min(SCALE_MAX / s_max);
216	        }
217	        // Fit: the cropped picture fitted at θ = 0 by `edit_zoom.rs`'s two
218	        // solves, written as F so it composes like any key.
219	        let whole = ZoomRegion {
220	            x: 0.0,
221	            y: 0.0,
222	            width: cw,
223	            height: ch,
224	        };
225	        let fit_scale = zoom_scale((w, h), &whole, ZoomFit::Fit, 0.0);
226	        let (fx, fy) = zoom_offset(&video, &whole, fit_scale);
227	        let kf = fit_scale / s;
228	        Some(Frame {
229	            anchor,
230	            s,
231	            media: (mw, mh),
232	            rect,
233	            k,
234	            window: (w / k, h / k),
235	            half_source: (ws / 2.0, hs / 2.0),
236	            fit: (kf, fx - kf * video.x, fy - kf * video.y),
237	            placed: Vec::new(),
238	        })
239	    }
240	
241	    /// A box point (0…1 of the picture) on the source canvas, through the
242	    /// placement in force at clip tick `t` (VR-27 (a)); the base's when
243	    /// none was read there.
244	    pub(crate) fn point(&self, t: Ticks, bx: f64, by: f64) -> Point {
245	        let (mw, mh) = self.media;
246	        let (s, anchor) = match self.placed.binary_search_by_key(&t, |p| p.0) {
247	            Ok(i) => {
248	                let (_, s, x, y) = self.placed[i];
249	                (s, (self.half_source.0 + x, self.half_source.1 + y))
250	            }
251	            Err(_) => (self.s, self.anchor),
252	        };
253	        (
254	            anchor.0 + s * (bx * mw - mw / 2.0),
255	            anchor.1 + s * (by * mh - mh / 2.0),
256	        )
257	    }
258	
259	    /// `wc` moved so the window lies inside the cropped rect (its centre
260	    /// when the window is the larger).
261	    pub(crate) fn clamp(&self, wc: Point) -> Point {
262	        let ((x0, y0), (x1, y1)) = self.rect;
263	        let axis = |v: f64, lo: f64, hi: f64| {
264	            if lo > hi {
265	                (lo + hi) / 2.0
266	            } else {
267	                v.clamp(lo, hi)
268	            }
269	        };
270	        (
271	            axis(wc.0, x0 + self.window.0 / 2.0, x1 - self.window.0 / 2.0),
272	            axis(wc.1, y0 + self.window.1 / 2.0, y1 - self.window.1 / 2.0),
273	        )
274	    }
275	
276	    /// The cropped rect's centre.
277	    pub(crate) fn centre(&self) -> Point {
278	        let ((x0, y0), (x1, y1)) = self.rect;
279	        ((x0 + x1) / 2.0, (y0 + y1) / 2.0)
280	    }
281	
282	    /// The `fit` state's key at `t`.
283	    pub(crate) fn fit_key(&self, t: Ticks, curve: Curve) -> FramingKey {
284	        let (scale, x, y) = self.fit;
285	        FramingKey {
286	            t,
287	            scale,
288	            x,
289	            y,
290	            curve,
291	        }
292	    }
293	
294	    pub(crate) fn key(&self, t: Ticks, wc: Point, curve: Curve) -> FramingKey {
295	        FramingKey {
296	            t,
297	            scale: self.k,
298	            x: self.k * (self.half_source.0 - wc.0),
299	            y: self.k * (self.half_source.1 - wc.1),
300	            curve,
301	        }
302	    }
303	
304	    /// VR-22: the subject point of a kind's box at clip tick `t`, and the
305	    /// window centre's offset from it.
306	    pub(crate) fn subject(
307	        &self,
308	        t: Ticks,
309	        kind: SubjectKind,
310	        b: &SubjectBox,
311	        headroom: f64,
312	    ) -> (Point, Point) {
313	        let (w, h) = self.window;
314	        match kind {
315	            SubjectKind::Face => {
316	                let lift = if h > w { h / 2.0 - headroom * h } else { 0.0 };
317	                (self.point(t, b.x + b.w / 2.0, b.y + b.h / 2.0), (0.0, lift))
318	            }
319	            SubjectKind::Person => (
320	                self.point(t, b.x + b.w / 2.0, b.y),
321	                (0.0, h / 2.0 - PERSON_TOP * h),
322	            ),
323	            SubjectKind::Salient => (self.point(t, b.x + b.w / 2.0, b.y + b.h / 2.0), (0.0, 0.0)),
324	        }
325	    }
326	}
