419	/// One key at 0 holding a `where_empty` state for the whole clip (spec §11
420	/// VR-24 (h), VR-26): `follow` `center` (the window at fill × `zoom` on the
421	/// cropped centre) and `fit` (the cropped picture fitted; `zoom` unread).
422	/// `None` for no such clip, no size, a base rotation other than 0, a zoom
423	/// outside 1…4, or a crop or scale that leaves no picture. Offsets are
424	/// measured from the canvas's own centre, so the source canvas is the
425	/// current one.
426	pub fn fixed_framing(
427	    project: &Project,
428	    clip: u32,
429	    state: WhereEmpty,
430	    zoom: f64,
431	) -> Option<FramingPath> {
432	    let clip = project.clip(clip)?;
433	    let request = FramingRequest {
434	        follow: Follow::Subject,
435	        zoom,
436	        from_width: project.canvas.width,
437	        from_height: project.canvas.height,
438	        where_empty: state,
439	    };
440	    let frame = Frame::of(project, clip, &request)?;
441	    let key = match state {
442	        WhereEmpty::Center => frame.key(0, frame.centre(), Curve::Linear),
443	        WhereEmpty::Fit => frame.fit_key(0, Curve::Linear),
444	    };
445	    Some(FramingPath {
446	        keys: vec![key],
447	        shows_fit: state == WhereEmpty::Fit,
448	        cuts: Vec::new(),
449	    })
450	}
