368	/// Refusal (6): a turned base, an action end turning the clip, or a spin.
369	fn turn_refusal(id: u32, clip: &Clip, video: &VideoProps) -> Option<String> {
370	    let upright = "framing works on an upright picture; only keep reframes it";
371	    if video.rotation != 0.0 {
372	        return Some(format!(
373	            "clip {id} is turned {}°, and {upright}",
374	            video.rotation
375	        ));
376	    }
377	    let turning = |a: &&Action| {
378	        a.end["video"]["rotation"]
379	            .as_f64()
380	            .is_some_and(|r| r != 0.0)
381	    };
382	    if let Some(action) = clip.actions.iter().find(turning) {
383	        return Some(format!(
384	            "clip {id}'s action {} turns it, and {upright}",
385	            action.id
386	        ));
387	    }
388	    let spins = video.motion.as_ref().is_some_and(|m| {
389	        [m.r#in, m.out]
390	            .iter()
391	            .flatten()
392	            .any(|e| e.kind == EdgeMotion::Spin)
393	            || m.during.is_some_and(|d| d.kind == DuringMotion::Spin)
394	    });
395	    spins.then(|| format!("clip {id} spins in its motion, and {upright}"))
396	}
