1	//! `reframe_clip {follow: "layout"}` — a camera and the screen behind it
2	//! re-laid on the current canvas (road map "creator-jobs" VR5b, spec §11
3	//! VR-53). Each switch Clip ▸ Camera Layout ▸ made is recognised on the
4	//! AUTHORED canvas (`from`, `layout_recognise.rs`) and solved again here by
5	//! `switch_layout`'s own composition (`compose_switch`), so a re-laid switch
6	//! is exactly the one a person would make on this canvas.
7	//!
8	//! - **The group.** Every top-level clip holding a layout action
9	//!   (`is_layout`) is laid out. A camera action at absolute T pairs with the
10	//!   layout action starting at T on the front-most track behind the
11	//!   camera's that holds one (CO-64's front and behind); a laid-out clip is
12	//!   a SCREEN when one on a track in front holds a layout action starting
13	//!   when one of its own does, else a CAMERA. The group is the closure over
14	//!   pairing from the given clip, plus each switch's PIECES: the clips of the
15	//!   same source (`same_source`, which ignores `in`) on a role's track
16	//!   starting after its action and before the track's next layout action,
17	//!   whose base is `alike` that action's end — the cut pieces of a laid-out
18	//!   recording, which CO-61's reach gave the layout as their base.
19	//! - **The replay.** Every group clip and piece takes `keep`'s per-axis
20	//!   rescale of its BASE (`rescale_video`); the group's layout actions are
21	//!   removed; the switches are composed again in time order at the camera
22	//!   action's absolute start, with [`switch_timing`]'s duration and curve,
23	//!   the recognised layout (Side by Side as Stacked on a canvas taller than
24	//!   wide) and its pieces as each role's later clips, nothing ending a
25	//!   reach. The focus is the old crop's centre (`focus_of`).
26	//! - **The other moves.** Each other moving end of a group clip or piece (a
27	//!   zoom) is re-based by [`conjugate`] from the placement in effect at its
28	//!   start on the old project to the one on the new, so what it zooms on
29	//!   keeps its place in the picture.
30	//!
31	//! Refused in VR-53 (c)'s order (`edit.rs`'s row); CO-62's refusals are not
32	//! asked again: each switch passed them when it was made.
33	
34	use std::collections::{BTreeSet, HashMap};
35	
36	use serde_json::{Map, Value};
37	
38	use crate::action_class::{is_layout, moves};
39	use crate::edit_canvas::rescale_video;
40	use crate::edit_layout_reach::{Role, RoleKind};
41	use crate::layout::{CameraLayout, LayoutChoice, Placement, DEFAULT_SWITCH};
42	use crate::layout_recognise::{alike, recognise, same_source};
43	use crate::model::{Action, Clip, Curve, Project};
44	use crate::outcome::Outcome;
45	use crate::props_check::{SCALE_MAX, SCALE_MIN};
46	use crate::time::Ticks;
47	
48	/// One layout action: its clip, its id and its absolute start.
49	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
50	struct Act {
51	    clip: u32,
52	    action: u32,
53	    at: Ticks,
54	}
55	
56	/// A recognised switch: the camera's action, the screen's paired one, the
57	/// layout, and each role's pieces.
58	struct Switch {
59	    camera: Act,
60	    screen: Option<Act>,
61	    choice: LayoutChoice,
62	    camera_pieces: Vec<u32>,
63	    screen_pieces: Vec<u32>,
64	}
65	
66	/// The duration and curve a switch is replayed with: those of its longest
67	/// role action that does not start at its clip's first frame (a cut there
68	/// is one frame long whatever the switch's length), else the camera
69	/// action's — `actions` holds the camera's first.
70	pub(crate) fn switch_timing(actions: &[(&Clip, &Action)]) -> (Ticks, Curve) {
71	    let mut chosen: Option<&Action> = None;
72	    for (_, action) in actions {
73	        if action.start != 0 && chosen.is_none_or(|c| action.duration > c.duration) {
74	            chosen = Some(action);
75	        }
76	    }
77	    match chosen.or(actions.first().map(|(_, a)| *a)) {
78	        Some(action) => (action.duration, action.curve),
79	        None => (DEFAULT_SWITCH, Curve::EaseInOut),
80	    }
81	}
82	
83	/// A moving end re-based from the placement `old` it was made over to
84	/// `new`: with `r = new.scale / old.scale`, each of `x`, `y` and `scale`
85	/// the end names is written `new.x + r·(x − old.x)`, `new.y + r·(y − old.y)`
86	/// and `scale·r` (clamped), so the picture point it shows at a canvas point
87	/// keeps its place relative to the layout's picture.
88	pub(crate) fn conjugate(end: &mut Map<String, Value>, old: &Placement, new: &Placement) {
89	    let r = new.scale / old.scale;
90	    if !(r.is_finite() && r > 0.0) {
91	        return;
92	    }
93	    let read = |end: &Map<String, Value>, key: &str| end.get(key).and_then(Value::as_f64);
94	    if let Some(x) = read(end, "x") {
95	        end.insert("x".into(), Value::from(new.x + r * (x - old.x)));
96	    }
97	    if let Some(y) = read(end, "y") {
98	        end.insert("y".into(), Value::from(new.y + r * (y - old.y)));
99	    }
100	    if let Some(scale) = read(end, "scale") {
101	        end.insert(
102	            "scale".into(),
103	            Value::from((scale * r).clamp(SCALE_MIN, SCALE_MAX)),
104	        );
105	    }
106	}
107	
108	/// The layout actions of `clip`, in its action order.
109	fn layout_acts(clip: &Clip) -> Vec<Act> {
110	    clip.actions
111	        .iter()
112	        .filter(|a| is_layout(a))
113	        .map(|a| Act {
114	            clip: clip.id,
115	            action: a.id,
116	            at: clip.start.saturating_add(a.start),
117	        })
118	        .collect()
119	}
120	
121	/// The placement in effect at clip time `t`: the latest layout end starting
122	/// at or before it, else the base.
123	fn in_effect(clip: &Clip, t: Ticks) -> Placement {
124	    clip.actions
125	        .iter()
126	        .filter(|a| is_layout(a) && a.start <= t)
127	        .max_by_key(|a| (a.start, a.id))
128	        .and_then(|a| Placement::from_end(&a.end))
129	        .unwrap_or_else(|| Placement::of(&clip.video.clone().unwrap_or_default()))
130	}
131	
132	impl Project {
133	    /// The layout action starting at absolute `at` on the front-most track
134	    /// behind `camera`'s that holds one.
135	    fn paired(&self, camera: &Clip, at: Ticks) -> Option<Act> {
136	        let front = self.track_index(camera.track)?;
137	        self.tracks.get(..front)?.iter().rev().find_map(|track| {
138	            self.clips
139	                .iter()
140	                .filter(|c| c.track == track.id && c.id != camera.id)
141	                .flat_map(layout_acts)
142	                .filter(|act| act.at == at)
143	                .min_by_key(|act| (act.clip, act.action))
144	        })
145	    }
146	
147	    /// Whether a laid-out clip on a track in front of `clip`'s holds a
148	    /// layout action starting when one of `clip`'s does.
149	    fn is_screen(&self, clip: &Clip) -> bool {
150	        let Some(own) = self.track_index(clip.track) else {
151	            return false;
152	        };
153	        let starts: Vec<Ticks> = layout_acts(clip).iter().map(|a| a.at).collect();
154	        self.clips.iter().any(|c| {
155	            c.id != clip.id
156	                && self.track_index(c.track).is_some_and(|i| i > own)
157	                && layout_acts(c).iter().any(|a| starts.contains(&a.at))
158	        })
159	    }
160	
161	    /// `act`'s clip and action.
162	    fn action_of(&self, act: &Act) -> Option<(&Clip, &Action)> {
163	        let owner = self.clip(act.clip)?;
164	        Some((owner, owner.actions.iter().find(|a| a.id == act.action)?))
165	    }
166	
167	    /// `act`'s end, and its clip's source size.
168	    fn end_of(&self, act: &Act) -> Option<(Placement, (f64, f64))> {
169	        let (owner, action) = self.action_of(act)?;
170	        Some((Placement::from_end(&action.end)?, self.source_size(owner)?))
171	    }
172	
173	    /// The pieces of `act`'s role (the module doc).
174	    fn pieces(&self, act: &Act) -> Vec<u32> {
175	        let Some((role, action)) = self.action_of(act) else {
176	            return Vec::new();
177	        };
178	        let Some(end) = Placement::from_end(&action.end) else {
179	            return Vec::new();
180	        };
181	        let next = self
182	            .clips
183	            .iter()
184	            .filter(|c| c.track == role.track)
185	            .flat_map(layout_acts)
186	            .map(|a| a.at)
187	            .filter(|&t| t > act.at)
188	            .min()
189	            .unwrap_or(Ticks::MAX);
190	        let mut found: Vec<&Clip> = self
191	            .clips
192	            .iter()
193	            .filter(|c| {
194	                c.id != role.id
195	                    && c.track == role.track
196	                    && same_source(&c.source, &role.source)
197	                    && c.start > act.at
198	                    && c.start < next
199	                    && self.has_layout_picture(c)
200	                    && c.video
201	                        .as_ref()
202	                        .is_some_and(|v| alike(&Placement::of(v), &end))
203	            })
204	            .collect();
205	        found.sort_by_key(|c| (c.start, c.id));
206	        found.iter().map(|c| c.id).collect()
207	    }
208	
209	    /// The first unrecognised switch's refusal, by its role's action.
210	    fn unrecognised(&self, act: &Act, from: (u32, u32)) -> Outcome {
211	        Outcome::Refused(format!(
212	            "clip {}'s layout action {} at {} is not a camera layout Frame Job made on the {} × {} \
213	             canvas, so it cannot be re-laid; keep its clips as placed",
214	            act.clip,
215	            act.action,
216	            self.layout_timecode(act.at),
217	            from.0,
218	            from.1
219	        ))
220	    }
221	
222	    /// `follow: layout` on `clip`, authored on a `from` canvas (the module
223	    /// doc).
224	    pub(crate) fn relaid(&self, clip: u32, from: (u32, u32)) -> Result<Outcome, String> {
225	        let given = self.require_clip(clip)?;
226	        if !given.actions.iter().any(is_layout) {
227	            return Ok(Outcome::Refused(format!(
228	                "clip {clip} holds no camera layout to re-lay; frame it with subject, center, fit \
229	                 or keep"
230	            )));
231	        }
232	        // Pairing over every laid-out clip, then the closure from `clip`.
233	        let edges: Vec<(Act, Act)> = self
234	            .clips
235	            .iter()
236	            .flat_map(|c| layout_acts(c).into_iter().map(move |act| (c, act)))
237	            .filter_map(|(c, act)| Some((act, self.paired(c, act.at)?)))
238	            .collect();
239	        let mut group: BTreeSet<u32> = BTreeSet::from([clip]);
240	        loop {
241	            let before = group.len();
242	            for (a, b) in &edges {
243	                if group.contains(&a.clip) || group.contains(&b.clip) {
244	                    group.insert(a.clip);
245	                    group.insert(b.clip);
246	                }
247	            }
248	            if group.len() == before {
249	                break;
250	            }
251	        }
252	        let clips: Vec<&Clip> = group.iter().filter_map(|id| self.clip(*id)).collect();
253	        let screens: HashMap<u32, bool> = clips.iter().map(|c| (c.id, self.is_screen(c))).collect();
254	
255	        // A clip both a camera and a screen.
256	        if let Some(both) = clips
257	            .iter()
258	            .find(|c| screens[&c.id] && edges.iter().any(|(a, _)| a.clip == c.id))
259	        {
260	            return Ok(Outcome::Refused(format!(
261	                "clip {} is laid out both as a camera and as a screen, so its layouts cannot be \
262	                 re-laid; keep its clips as placed",
263	                both.id
264	            )));
265	        }
266	        // A screen action with no camera switch in front of it.
267	        let unpaired = clips
268	            .iter()
269	            .filter(|c| screens[&c.id])
270	            .flat_map(|c| layout_acts(c))
271	            .filter(|act| !edges.iter().any(|(_, s)| s == act))
272	            .min_by_key(|act| (act.at, act.clip, act.action));
273	        if let Some(act) = unpaired {
274	            return Ok(Outcome::Refused(format!(
275	                "clip {}'s layout action {} at {} has no camera switch in front of it, so it \
276	                 cannot be re-laid; keep its clips as placed",
277	                act.clip,
278	                act.action,
279	                self.layout_timecode(act.at)
280	            )));
281	        }
282	
283	        // Each switch recognised on the authored canvas, in time order.
284	        let mut authored = self.clone();
285	        authored.canvas.width = from.0;
286	        authored.canvas.height = from.1;
287	        let mut acts: Vec<Act> = clips
288	            .iter()
289	            .filter(|c| !screens[&c.id])
290	            .flat_map(|c| layout_acts(c))
291	            .collect();
292	        acts.sort_by_key(|act| (act.at, act.clip, act.action));
293	        let mut switches: Vec<Switch> = Vec::new();
294	        for camera in acts {
295	            let screen = edges.iter().find(|(a, _)| *a == camera).map(|(_, s)| *s);
296	            let found = match (self.end_of(&camera), screen.map(|s| self.end_of(&s))) {
297	                (None, _) => Err(RoleKind::Camera),
298	                (Some(_), Some(None)) => Err(RoleKind::Screen),
299	                (Some(cam), shown) => {
300	                    let shown = shown.flatten();
301	                    let shown = shown.as_ref().map(|(end, size)| (end, *size));
302	                    recognise(&authored, &cam.0, cam.1, shown)
303	                }
304	            };
305	            let choice = match found {
306	                Ok(choice) => choice,
307	                Err(kind) => {
308	                    let named = screen.filter(|_| kind == RoleKind::Screen);
309	                    return Ok(self.unrecognised(&named.unwrap_or(camera), from));
310	                }
311	            };
312	            switches.push(Switch {
313	                camera,
314	                screen,
315	                choice,
316	                camera_pieces: self.pieces(&camera),
317	                screen_pieces: screen.map_or_else(Vec::new, |s| self.pieces(&s)),
318	            });
319	        }
320	
321	        // The members: the group's clips and every switch's pieces.
322	        let mut members: BTreeSet<u32> = group.clone();
323	        for s in &switches {
324	            members.extend(s.camera_pieces.iter().chain(&s.screen_pieces));
325	        }
326	        let (w, h) = (
327	            f64::from(self.canvas.width) / f64::from(from.0),
328	            f64::from(self.canvas.height) / f64::from(from.1),
329	        );
330	        let mut next = self.clone();
331	        for c in next.clips.iter_mut().filter(|c| members.contains(&c.id)) {
332	            if let Some(video) = c.video.as_mut() {
333	                rescale_video(video, w, h);
334	            }
335	            if group.contains(&c.id) {
336	                c.actions.retain(|a| !is_layout(a));
337	            }
338	        }
339	
340	        // The replay, in time order.
341	        let tall = self.canvas.height > self.canvas.width;
342	        for s in &switches {
343	            let mut choice = s.choice;
344	            if tall && choice.layout == CameraLayout::SideBySide {
345	                choice.layout = CameraLayout::Stacked;
346	            }
347	            let timed: Vec<(&Clip, &Action)> = std::iter::once(s.camera)
348	                .chain(s.screen)
349	                .filter_map(|act| self.action_of(&act))
350	                .collect();
351	            let (duration, curve) = switch_timing(&timed);
352	            let outcome = {
353	                let role = |kind: RoleKind, act: &Act, pieces: &[u32]| -> Option<Role<'_>> {
354	                    Some(Role {
355	                        kind,
356	                        clip: next.clip(act.clip)?,
357	                        at: act.at,
358	                        later: pieces.iter().filter_map(|id| next.clip(*id)).collect(),
359	                        ender: None,
360	                    })
361	                };
362	                let mut roles = Vec::new();
363	                roles.extend(role(RoleKind::Camera, &s.camera, &s.camera_pieces));
364	                if let Some(screen) = &s.screen {
365	                    roles.extend(role(RoleKind::Screen, screen, &s.screen_pieces));
366	                }
367	                next.compose_switch(&choice, &roles, s.camera.at, duration, curve)
368	            };
369	            match outcome? {
370	                Outcome::Applied(applied) => next = applied,
371	                Outcome::Identity => {}
372	                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
373	            }
374	        }
375	
376	        // The other moving ends, re-based.
377	        for id in &members {
378	            let (Some(old), Some(new)) = (self.clip(*id), next.clip(*id)) else {
379	                continue;
380	            };
381	            let bases: Vec<(usize, Placement, Placement)> = new
382	                .actions
383	                .iter()
384	                .enumerate()
385	                .filter(|(_, a)| moves(a) && !is_layout(a))
386	                .map(|(i, a)| (i, in_effect(old, a.start), in_effect(new, a.start)))
387	                .collect();
388	            let Some(target) = next.clips.iter_mut().find(|c| c.id == *id) else {
389	                continue;
390	            };
391	            for (i, was, now) in bases {
392	                if let Some(Value::Object(end)) = target.actions[i].end.get_mut("video") {
393	                    conjugate(end, &was, &now);
394	                }
395	            }
396	        }
397	        self.finish(next)
398	    }
399	}
