328	/// The samples and shots in clip time (VR-20): kept when in the played
329	/// window, ascending, one sample per clip tick (the earliest media tick's),
330	/// one shot per tick, a cut at 0 or at or past the end dropped.
331	pub(crate) fn in_clip_time(
332	    clip: &Clip,
333	    project: &Project,
334	    subjects: &Subjects,
335	) -> (Vec<SubjectSample>, Vec<Ticks>) {
336	    let Source::Media { media, .. } = clip.source else {
337	        return (Vec::new(), Vec::new());
338	    };
339	    let Some(media) = project.media(media) else {
340	        return (Vec::new(), Vec::new());
341	    };
342	    let at = |t: Ticks| {
343	        in_played_window(clip, media, t)
344	            .then(|| clip_time_of_source(clip, media, t, Round::Down))
345	            .flatten()
346	    };
347	    let mut samples: Vec<(Ticks, Ticks, &SubjectSample)> = subjects
348	        .samples
349	        .iter()
350	        .filter_map(|s| at(s.t).map(|c| (c, s.t, s)))
351	        .collect();
352	    samples.sort_by_key(|&(c, m, _)| (c, m));
353	    samples.dedup_by_key(|&mut (c, _, _)| c);
354	    // A shot rounds UP (VR-24 (a)): its clip tick is the first that shows
355	    // the new shot, where a sample's rounds down.
356	    let at_up = |t: Ticks| {
357	        in_played_window(clip, media, t)
358	            .then(|| clip_time_of_source(clip, media, t, Round::Up))
359	            .flatten()
360	    };
361	    let mut shots: Vec<Ticks> = subjects
362	        .shots
363	        .iter()
364	        .filter_map(|&t| at_up(t))
365	        .filter(|&c| c > 0 && c < clip.duration)
366	        .collect();
367	    shots.sort_unstable();
368	    shots.dedup();
369	    let samples = samples
370	        .into_iter()
371	        .map(|(c, _, s)| SubjectSample { t: c, ..s.clone() })
372	        .collect();
373	    (samples, shots)
374	}
