92	    /// Lays out `s.camera` and its screen at `s.at` (this module's doc).
93	    pub fn switch_layout(&self, s: &LayoutSwitch) -> Result<Outcome, String> {
94	        let at = self.snapped(s.at);
95	        if at < 0 {
96	            return Err(format!("at must not be negative, not {}", s.at));
97	        }
98	        let duration = match s.duration {
99	            None => DEFAULT_SWITCH,
100	            Some(given) => {
101	                let snapped = self.snapped(given);
102	                if snapped <= 0 {
103	                    return Err(format!("duration must be positive, not {given}"));
104	                }
105	                snapped
106	            }
107	        };
108	        let through = match s.through {
109	            None => None,
110	            Some(given) => {
111	                let snapped = self.snapped(given);
112	                if snapped <= at {
113	                    return Err(format!("through must be after at ({at}), not {given}"));
114	                }
115	                Some(snapped)
116	            }
117	        };
118	        let focus = match s.focus {
119	            None => (0.0, 0.0),
120	            Some([x, y]) if x.is_finite() && y.is_finite() => (x, y),
121	            Some([x, y]) => {
122	                return Err(format!("focus must be two finite numbers, not [{x}, {y}]"))
123	            }
124	        };
125	        let choice = LayoutChoice {
126	            layout: s.layout,
127	            shape: s.shape.unwrap_or_default(),
128	            corner: s.corner.unwrap_or_default(),
129	            focus,
130	        };
