1	//! How far a camera-layout switch reaches, and what in that reach refuses
2	//! it (road map "creator-jobs" CO6, spec §11 CO-61, CO-62): a part of
3	//! `edit_layout.rs`, cut beside it for the 400-line cap on a new module.
4	//!
5	//! A [`Role`] is the camera or the screen: the clip under `at`, and the
6	//! REACH's later clips — every picture clip on the same track starting
7	//! after `at` and before the earliest of the first later layout action's
8	//! absolute start on that track, `through` and the track's end.
9	
10	use crate::action_class::{is_layout, is_zoom, moves};
11	use crate::edit_clip::clip_end;
12	use crate::layout::{full_placement, holds_full, CameraLayout, Placement};
13	use crate::model::{Clip, Project};
14	use crate::time::Ticks;
15	
16	/// Which role a clip plays.
17	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
18	pub(crate) enum RoleKind {
19	    Camera,
20	    Screen,
21	}
22	
23	impl RoleKind {
24	    /// The role's word in a sentence.
25	    fn word(self) -> &'static str {
26	        match self {
27	            RoleKind::Camera => "camera",
28	            RoleKind::Screen => "screen",
29	        }
30	    }
31	}
32	
33	/// One role's clips in the reach.
34	#[derive(Debug, Clone)]
35	pub(crate) struct Role<'a> {
36	    pub kind: RoleKind,
37	    /// The clip playing at `at`.
38	    pub clip: &'a Clip,
39	    /// `at` in project time.
40	    pub at: Ticks,
41	    /// The later picture clips starting inside the reach, in time order.
42	    pub later: Vec<&'a Clip>,
43	    /// The clip whose own layout action ends the reach, when one does.
44	    pub ender: Option<u32>,
45	}
46	
47	impl<'a> Role<'a> {
48	    /// The clip under `at`, then the later reach clips.
49	    pub(crate) fn clips(&self) -> impl Iterator<Item = &'a Clip> + '_ {
50	        std::iter::once(self.clip).chain(self.later.iter().copied())
51	    }
52	
53	    /// What `nest: true` nests: [`Role::clips`] but a later clip whose own
54	    /// layout action ends the reach (CO-62).
55	    pub(crate) fn nested(&self) -> impl Iterator<Item = &'a Clip> + '_ {
56	        let ender = self.ender;
57	        std::iter::once(self.clip).chain(
58	            self.later
59	                .iter()
60	                .copied()
61	                .filter(move |c| Some(c.id) != ender),
62	        )
63	    }
64	}
65	
66	impl Project {
67	    /// The role `kind` played by `clip` (which plays at `at`), its reach
68	    /// found on `clip`'s track (CO-61).
69	    pub(crate) fn role<'a>(
70	        &'a self,
71	        kind: RoleKind,
72	        clip: &'a Clip,
73	        at: Ticks,
74	        through: Option<Ticks>,
75	    ) -> Role<'a> {
76	        let on_track = || self.clips.iter().filter(move |c| c.track == clip.track);
77	        let mut end = on_track().map(clip_end).max().unwrap_or(at);
78	        let mut ender = None;
79	        for owner in on_track() {
80	            for action in owner.actions.iter().filter(|a| is_layout(a)) {
81	                let starts = owner.start.saturating_add(action.start);
82	                if starts > at && starts < end {
83	                    end = starts;
84	                    ender = Some(owner.id);
85	                }
86	            }
87	        }
88	        if let Some(through) = through {
89	            if through < end {
90	                end = through;
91	                ender = None;
92	            }
93	        }
94	        let mut later: Vec<&Clip> = on_track()
95	            .filter(|c| c.id != clip.id && c.start > at && c.start < end)
96	            .filter(|c| self.has_layout_picture(c))
97	            .collect();
98	        later.sort_by_key(|c| (c.start, c.id));
99	        Role {
100	            kind,
101	            clip,
102	            at,
103	            later,
104	            ender,
105	        }
106	    }
107	
108	    /// The first mover in `role`'s reach, as CO-62's sentence, or `None`.
109	    /// A screen that already holds its full placement is not checked in a
110	    /// layout that leaves it there.
111	    pub(crate) fn mover_refusal(&self, role: &Role<'_>, layout: CameraLayout) -> Option<String> {
112	        let exempt = |clip: &Clip, placed: Placement| {
113	            role.kind == RoleKind::Screen
114	                && layout.screen_full()
115	                && self
116	                    .source_size(clip)
117	                    .is_some_and(|size| holds_full(&placed, &full_placement(self, size)))
118	        };
119	        for clip in role.clips() {
120	            let under = clip.id == role.clip.id;
121	            let t = role.at - clip.start;
122	            let placed = if under {
123	                Placement::of(&self.evaluate_clip(clip, t).video)
124	            } else {
125	                Placement::of(&clip.video.clone().unwrap_or_default())
126	            };
127	            if exempt(clip, placed) {
128	                continue;
129	            }
130	            let found = clip
131	                .actions
132	                .iter()
133	                .filter(|a| moves(a) && !is_layout(a))
134	                .filter(|a| !under || a.start.saturating_add(a.duration) > t)
135	                .min_by_key(|a| (a.start, a.id));
136	            if let Some(action) = found {
137	                let role_word = role.kind.word();
138	                let (verb, noun) = if is_zoom(action) {
139	                    ("zooms", "zoom")
140	                } else {
141	                    ("moves", "action")
142	                };
143	                return Some(format!(
144	                    "The {role_word} clip {} at {} {verb} (action {}); nest the {role_word}'s \
145	                     clips so the layout moves the nest and the {noun} stays inside it.",
146	                    clip.id,
147	                    self.layout_timecode(clip.start),
148	                    action.id
149	                ));
150	            }
151	        }
152	        None
153	    }
154	
155	    /// Whether `clip` is already laid out (CO-62): its base six keys, or the
156	    /// end of any of its layout actions, not its full placement.
157	    pub(crate) fn laid_out(&self, clip: &Clip) -> bool {
158	        let Some(size) = self.source_size(clip) else {
159	            return false;
160	        };
161	        let full = full_placement(self, size);
162	        let base = Placement::of(&clip.video.clone().unwrap_or_default());
163	        !holds_full(&base, &full)
164	            || clip
165	                .actions
166	                .iter()
167	                .filter(|a| is_layout(a))
168	                .any(|a| Placement::from_end(&a.end).is_none_or(|end| !holds_full(&end, &full)))
169	    }
170	}
