3	/// Make Vertical's `follow: speaker` (road map "creator-jobs" VR6b, spec §11 VR-64, VR-66): which
4	/// tracks are microphones, which pictures are framed by who is talking and with which of them,
5	/// the turns filled on main, and what the sheet reads to confirm the match. The step itself is
6	/// `VerticalVersion+Plan.swift`'s; the match is the core's (`ReelProject.speakerMatch`, VR-65).
7	/// Swift restates none of VR-60's refusals: a microphone the core will not take reaches the
8	/// clip's entry in its own sentence. Names no `rc_*`.
9	extension VerticalVersion {
10	    /// A track the sheet offers as a microphone (VR-66 (b)): its name, and the clip that stands
11	    /// for it in `mics`, the earliest that plays a sound file.
12	    struct Microphone: Equatable {
13	        let track: UInt32
14	        let name: String
15	        let clip: UInt32
16	    }
17	
18	    /// A picture framed by who is talking (VR-64 (b)), with its own microphones — one clip per
19	    /// microphone track that sounds under it, in `mics`' order — and their faces when given.
20	    struct SpeakerClip: Equatable {
21	        let clip: UInt32
22	        let mics: [UInt32]
23	        let micFaces: [UInt32]?
24	    }
25	
26	    /// A clip the step framed with `speaker` (VR-64 (f)): its microphones and the face of each,
27	    /// given or the core's own match.
28	    struct SpeakerFraming: Equatable {
29	        let clip: UInt32
30	        let mics: [UInt32]
31	        let faces: [UInt32]
32	    }
33	
34	    /// What the sheet reads for Speaker (VR-66 (c)): a refusal's sentence, or the subjects with
35	    /// their turns, the reference clip and the core's match on it.
36	    enum SpeakerReading {
37	        case refused(String)
38	        case ready(subjects: [UInt32: [String: Any]], reference: UInt32, match: SpeakerMatch?)
39	    }
40	
41	    /// The tool's refusal with no speaker clip (VR-64 (e)).
42	    static let noSpeakerClip =
43	        "make_vertical_version found no full-frame movie clip playing beside two of the "
44	        + "microphones in mics, so nobody is framed by who is talking."
45	
46	    /// The sheet's sentence with no speaker clip (VR-66 (c)).
47	    static let noSpeakerClipSheet =
48	        "No full-frame movie clip plays beside two of the ticked microphones, so nobody can be "
49	        + "framed by who is talking."
50	
51	    /// VR-66 (b): each track, front to back, holding a clip `SpeakerSwitch.playsSound` takes
52	    /// whose media has no picture; its `clip` the earliest such clip (ties: the lower id).
53	    static func microphones(_ project: ReelProject) -> [Microphone] {
54	        let snapshot = project.snapshot
55	        return snapshot.tracks.reversed().compactMap { track in
56	            let sounding = snapshot.clips(onTrack: track.id).filter {
57	                SpeakerSwitch.playsSound($0, in: snapshot)
58	                    && snapshot.media(for: $0)?.hasVideo == false
59	            }
60	            guard let first = sounding.min(by: { ($0.start, $0.id) < ($1.start, $1.id) })
61	            else { return nil }
62	            return Microphone(track: track.id, name: track.name, clip: first.id)
63	        }
64	    }
65	
66	    /// VR-64 (b): the present, cursor-free class-3 media pictures off the microphone tracks whose
67	    /// span overlaps a clip with audio on at least two of them, in id order; [] unless `follow`
68	    /// is `speaker`. Each one's `mics` are, per microphone in order, the media clip with audio on
69	    /// that microphone's track with the greatest overlap (ties: the earlier start, then the lower
70	    /// id); a track with none is left out with its `micFaces` entry. A `micFaces` that is not
71	    /// one per microphone is passed as given, for the core to refuse in its own sentence.
72	    static func speakerClips(
73	        _ project: ReelProject, settings: VerticalSettings, missing: Set<UInt32>
74	    ) -> [SpeakerClip] {
75	        guard settings.follow == .speaker else { return [] }
76	        let snapshot = project.snapshot
77	        let micTracks = settings.mics.map { snapshot.clip($0)?.track }
78	        let onMics = Set(micTracks.compactMap { $0 })
79	        let given = settings.micFaces
80	        let filters = given.map { $0.count == settings.mics.count } ?? false
81	        var out: [SpeakerClip] = []
82	        for id in mediaPictures(classify(project), in: snapshot) where !missing.contains(id) {
83	            guard let clip = snapshot.clip(id), snapshot.media(for: clip)?.cursor == nil,
84	                !onMics.contains(clip.track)
85	            else { continue }
86	            var mics: [UInt32] = []
87	            var faces: [UInt32] = []
88	            for (n, track) in micTracks.enumerated() {
89	                guard let track, let best = loudest(on: track, under: clip, in: snapshot)
90	                else { continue }
91	                mics.append(best)
92	                if filters, let given { faces.append(given[n]) }
93	            }
94	            guard mics.count >= 2 else { continue }
95	            out.append(SpeakerClip(clip: id, mics: mics, micFaces: filters ? faces : given))
96	        }
97	        return out
98	    }
