3	/// Make Vertical's summary (spec §11 VR-35) and its answer (VR-36): what `plan` did, said as
4	/// the sheet's and the tool's text and as `make_vertical_version`'s keys. A pure move out of
5	/// `VerticalVersion+Plan.swift` (road map "creator-jobs" VR5b's toll). Names no `rc_*`.
6	extension VerticalVersion {
7	    /// VR-35: the counts, then one line per re-laid switch (VR-54), then one line per entry
8	    /// with a reason; the graphic counts and lines VR4b's (`templates`, VR-44 (d)).
9	    static func summary(_ plan: Plan, templates: TemplateReport = TemplateReport()) -> String {
10	        func count(_ treatment: Treatment) -> Int {
11	            plan.entries.filter { $0.treatment == treatment }.count
12	        }
13	        var text = "Makes a \(plan.width) × \(plan.height) version."
14	        let followed = count(.followed)
15	        if followed > 0 { text += " Follows \(counted(followed, "clip"))." }
16	        if !plan.cursor.isEmpty {
17	            text += " Follows the cursor in \(counted(plan.cursor.count, "clip")), their own "
18	                + "zooms and pans replaced."
19	        }
20	        if !plan.speaker.isEmpty {
21	            text += " Follows whoever is talking in \(counted(plan.speaker.count, "clip"))."
22	        }
23	        if !plan.relaid.isEmpty {
24	            text += " Re-lays \(counted(plan.relaid.count, "camera layout")) for the new canvas."
25	        }
26	        let whole = count(.whole)
27	        if whole > 0 { text += " Shows \(counted(whole, "clip")) whole on a blurred copy." }
28	        let kept = count(.kept)
29	        if kept > 0 { text += " Keeps \(counted(kept, "clip")) as placed." }
30	        let refilled = count(.refilled)
31	        if refilled > 0 { text += " Re-fills \(counted(refilled, "background"))." }
32	        let removed = count(.removed)
33	        if removed > 0 {
34	            text += " Removes \(removed) blurred \(removed == 1 ? "copy" : "copies") the "
35	                + "framing replaces."
36	        }
37	        text += graphicsCounts(plan, templates)
38	        if plan.backgrounds { text += " Adds a Backgrounds track for the blurred copy." }
39	        if plan.moreTracks > 0 {
40	            text += " Adds \(plan.moreTracks) more \(plan.moreTracks == 1 ? "track" : "tracks")"
41	                + " behind it where clips overlap."
42	        }
43	        if plan.reEased > 0 { text += " \(counted(plan.reEased, "action")) re-eased at a cut." }
44	        if plan.carried > 0 {
45	            text += " \(counted(plan.carried, "action")) "
46	                + (plan.carried == 1 ? "carries" : "carry") + " a framing move."
47	        }
48	        if let relaid = plan.captions?.relaid.count, relaid > 0 {
49	            text += " Re-lays \(counted(relaid, "caption track")) for the new canvas."
50	        }
51	        let canvas = plan.project.snapshot.canvas
52	        var lines = [text] + plan.relaid.map { relaidLine($0, canvas: canvas) }
53	        for entry in plan.entries {
54	            guard let reason = entry.reason else { continue }
55	            let why = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
56	            switch entry.treatment {
57	            case .notFollowed: lines.append("Clip \(entry.clip) is not followed: \(why).")
58	            default: lines.append("Clip \(entry.clip) is followed, but \(why).")
59	            }
60	        }
61	        lines += (plan.captions?.kept ?? []).map(CaptionRelayout.keptLine)
62	        lines += graphicsLines(templates)
63	        return lines.joined(separator: "\n")
64	    }
65	
66	    /// VR-39 (d)'s pending summary, while the analysis is still to be made; with `speaker` it
67	    /// says the sheet comes back to confirm the microphones' faces (VR-66 (e)).
68	    static func pendingSummary(files: Int, width: Int, height: Int, speaker: Bool = false)
69	        -> String
70	    {
71	        "Finds the faces, people and shot changes in \(counted(files, "file")) on this Mac "
72	            + "first, " + (speaker ? "then asks you to confirm who is on each microphone, " : "")
73	            + "then makes a \(width) × \(height) version."
74	    }
75	
76	    /// The answer's keys every door shares (VR-36): `canvas`, `clips` in id order,
77	    /// `backgrounds`, `more_tracks`, `re_eased`, `moves_carried`, `summary`, `graphics`,
78	    /// `cursor` (VR-52), `relaid` (VR-54) and `speaker` (VR-64 (f)).
79	    static func answerFields(_ plan: Plan, templates: TemplateReport = TemplateReport())
80	        -> [String: Any]
81	    {
82	        let clips: [[String: Any]] = plan.entries.map { entry in
83	            var row: [String: Any] = [
84	                "clip": Int(entry.clip), "treatment": entry.treatment.rawValue,
85	            ]
86	            if let reason = entry.reason { row["reason"] = reason }
87	            return row
88	        }
89	        var fields: [String: Any] = [
90	            "canvas": ["width": plan.width, "height": plan.height],
91	            "clips": clips,
92	            "backgrounds": plan.backgrounds,
93	            "more_tracks": plan.moreTracks,
94	            "re_eased": plan.reEased,
95	            "moves_carried": plan.carried,
96	            "summary": summary(plan, templates: templates),
97	            "cursor": plan.cursor.map { Int($0) },
98	            "relaid": relaidFields(plan.relaid),
99	            "speaker": plan.speaker.map { framed -> [String: Any] in
100	                [
101	                    "clip": Int(framed.clip), "mics": framed.mics.map { Int($0) },
102	                    "mic_faces": framed.faces.map { Int($0) },
103	                ]
104	            },
105	            "graphics": graphicsFields(plan, templates),
106	        ]
107	        if let captions = plan.captions {
