4	/// Make Vertical's graphics (spec §11 VR-42, VR-44; road map "creator-jobs" VR4b): a graphic the
5	/// old canvas's size re-sized to the new one in step (4) (`graphicOps`), and a project's own
6	/// copies of road map 10's six templates surveyed by revision (`templateSurvey`), rewritten with
7	/// the bundled text only in a copy (`updateTemplates`, `ProjectDocument+VerticalCopy.swift`) and
8	/// listed otherwise, with the answer's `graphics` and the summary's graphic lines. The table is
9	/// `GraphicTemplates+Revisions.swift`'s. Names no `rc_*`.
10	extension VerticalVersion {
11	
12	    /// VR-42 (b): `set_graphic {width, height}` to the new canvas; the base x and y, when either
13	    /// is non-zero, and each action end's named x and y by the axis ratios. Scale is never
14	    /// touched: the graphic is the canvas's size again, so its scale means what it meant.
15	    static func graphicOps(
16	        _ clip: ClipSnapshot, from old: CanvasSnapshot, width: Int, height: Int
17	    ) -> [ReelOp] {
18	        let rx = Double(width) / Double(max(1, old.width))
19	        let ry = Double(height) / Double(max(1, old.height))
20	        var ops: [ReelOp] = [
21	            .setGraphicRaw(clips: [clip.id], patch: ["width": width, "height": height])
22	        ]
23	        let video = clip.videoProps
24	        if video.x != 0 || video.y != 0 {
25	            ops.append(
26	                .setVideo(clips: [clip.id], patch: VideoPatch(x: video.x * rx, y: video.y * ry)))
27	        }
28	        for action in clip.actions {
29	            guard let end = action.end.video, end.x != nil || end.y != nil else { continue }
30	            var moved: [String: Any] = [:]
31	            if let x = end.x { moved["x"] = x * rx }
32	            if let y = end.y { moved["y"] = y * ry }
33	            ops.append(.setActionEndRaw(clip: clip.id, action: action.id, patch: ["video": moved]))
34	        }
35	        return ops
36	    }
37	
38	    /// VR-44 (b): the drawn modules that are an older copy of a bundled template (module →
39	    /// stem) and those matching no shipped revision that size themselves by height (sorted).
40	    struct TemplateSurvey: Equatable {
41	        var outdated: [String: String] = [:]
42	        var byHeight: [String] = []
43	    }
44	
45	    /// VR-44 (d): what was (or will be) updated and what is listed, both by name.
46	    struct TemplateReport: Equatable {
47	        struct Listed: Equatable {
48	            let name: String
49	            let reason: String
50	        }
51	        var updated: [String] = []
52	        var listed: [Listed] = []
53	    }
54	
55	    static let byHeightReason =
56	        "it sizes itself by the canvas's height, so it may not fit the narrow frame"
57	
58	    static func inPlaceReason(_ stem: String) -> String {
59	        "it is an older copy of the bundled template \"\(stem)\"; Make Vertical updates it only "
60	            + "in a copy"
61	    }
62	
63	    /// The SHA-256 of a bundled template's text, nil when it cannot be read.
64	    private static func bundledRevision(_ stem: String, in bundled: URL) -> String? {
65	        let url = bundled.appendingPathComponent(stem + ".js")
66	        guard let bytes = try? Data(contentsOf: url) else { return nil }
67	        return GraphicStore.hex(SHA256.hash(data: bytes))
68	    }
69	
70	    /// VR-44 (b), main: over `DerivedCarry.drawnGraphicNames`, each name's scanned module —
71	    /// outdated when its revision is a shipped row for stem S other than the readable bundled
72	    /// `<S>.js`'s (by revision, never by name); by height when no row matches and its text
73	    /// measures by `ctx.height / 1080`. No store, an empty survey.
74	    static func templateSurvey(
75	        _ project: ReelProject, store: GraphicStore?,
76	        bundled: URL = GraphicTemplates.bundledDirectory
77	    ) -> TemplateSurvey {
78	        var survey = TemplateSurvey()
79	        guard let store else { return survey }
80	        var current: [String: String?] = [:]
81	        for name in DerivedCarry.drawnGraphicNames(project.snapshot).sorted() {
82	            guard let module = store.module(named: name) else { continue }
83	            if let stem = GraphicTemplates.shippedRevisions[module.revision] {
84	                if current[stem] == nil { current[stem] = bundledRevision(stem, in: bundled) }
85	                if let now = current[stem] ?? nil, now != module.revision {
86	                    survey.outdated[name] = stem
87	                }
88	            } else if GraphicTemplates.measuresByHeight(
89	                String(decoding: module.bytes, as: UTF8.self))
90	            {
91	                survey.byHeight.append(name)
92	            }
93	        }
94	        return survey
95	    }
96	
97	    /// VR-44 (c), predicted: with `copy` the outdated modules are updated; without it each is
98	    /// listed with the in-place reason. Both list the modules that size by height.
99	    static func templateReport(_ survey: TemplateSurvey, copy: Bool) -> TemplateReport {
100	        var report = TemplateReport()
101	        var listed = survey.byHeight.map { TemplateReport.Listed(name: $0, reason: byHeightReason) }
102	        if copy {
103	            report.updated = survey.outdated.keys.sorted()
104	        } else {
105	            listed += survey.outdated.map {
106	                TemplateReport.Listed(name: $0.key, reason: inPlaceReason($0.value))
107	            }
108	        }
109	        report.listed = listed.sorted { $0.name < $1.name }
110	        return report
111	    }
112	
113	    /// VR-44 (c), main, the copy only: each outdated module rewritten with the bundled text
114	    /// through `store.write(name:source:)`, then ONE `rescan()`, whose pass keeps the replaced
115	    /// text as the module's history (`keepReplaced`). A failure lists the module.
116	    static func updateTemplates(
117	        _ survey: TemplateSurvey, in store: GraphicStore, from bundled: URL
118	    ) -> TemplateReport {
119	        var report = TemplateReport()
120	        var listed = survey.byHeight.map { TemplateReport.Listed(name: $0, reason: byHeightReason) }
121	        for (name, stem) in survey.outdated.sorted(by: { $0.key < $1.key }) {
122	            do {
123	                let source = try String(
124	                    contentsOf: bundled.appendingPathComponent(stem + ".js"), encoding: .utf8)
125	                try store.write(name: name, source: source)
126	                report.updated.append(name)
127	            } catch {
128	                listed.append(
129	                    TemplateReport.Listed(
130	                        name: name,
131	                        reason: "it could not be updated: \(error.localizedDescription)"))
132	            }
133	        }
134	        if !survey.outdated.isEmpty { store.rescan() }
135	        report.listed = listed.sorted { $0.name < $1.name }
136	        return report
137	    }
138	
139	    /// The answer's `graphics {resized, updated, listed [{name, reason}]}` (VR-36 as amended).
140	    static func graphicsFields(_ plan: Plan, _ templates: TemplateReport) -> [String: Any] {
141	        [
142	            "resized": plan.entries.filter { $0.treatment == .resized }.count,
143	            "updated": templates.updated,
144	            "listed": templates.listed.map { ["name": $0.name, "reason": $0.reason] },
145	        ]
146	    }
147	
148	    /// The summary's graphic counts, after the removed copies (VR-35 as amended).
149	    static func graphicsCounts(_ plan: Plan, _ templates: TemplateReport) -> String {
150	        var text = ""
151	        let resized = plan.entries.filter { $0.treatment == .resized }.count
152	        if resized > 0 { text += " Re-sizes \(counted(resized, "graphic")) to the new canvas." }
153	        let updated = templates.updated.count
154	        if updated > 0 {
155	            text += " Updates \(counted(updated, "graphic module")) to the current template."
156	        }
157	        return text
158	    }
159	
160	    /// One line per listed module, after the caption lines.
161	    static func graphicsLines(_ templates: TemplateReport) -> [String] {
162	        templates.listed.map { "Graphic module \"\($0.name)\" is left as it is: \($0.reason)." }
163	    }
164	}
